	private bool registered;

	public bool isChargeSkill;

	public static SyncedNumVarStat WindupMultiStat
	{
		get
		{
			if (windupMultiStat == null)
			{
				windupMultiStat = new SyncedNumVarStat(1f);
			}
			return windupMultiStat;
		}
	}

	public static SyncedNumVarStat ExitMultiStat
	{
		get
		{
			if (exitMultiStat == null)
			{
				exitMultiStat = new SyncedNumVarStat(1f);
			}
			return exitMultiStat;
		}
	}

	public static SyncedNumVarStat CooldownMultiStat
	{
		get
		{
			if (cooldownMultiStat == null)
			{
				cooldownMultiStat = new SyncedNumVarStat(1f);
			}
			return cooldownMultiStat;
		}
	}

	public virtual float StdWindupTime => Mathf.Lerp(0.5f, 0.35f, currentDiffValue) * WindupMultiStat.CurrentValue;

	public virtual float StdExitTime => Mathf.Lerp(0.75f, 0.5f, currentDiffValue) * ExitMultiStat.CurrentValue;

	public virtual bool WindupCheck => windupComplete;

	public SkillState(string newName, FSM newFSM, Enemy newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
		: base(newName, newFSM, newEnt)
	{
		skillID = newName;
		requiredDifficultyLevel = newReq;
		priorityLevel = newPriority;
		minActivationRadius = newMin;
		maxActivationRadius = newMax;
		cooldownTime = Mathf.Max(2f, newCD * CooldownMultiStat.CurrentValue);
		RegisterSkill(newAuto);
	}

	public static void ApplyGlobalMods(NumVarStatMod givenCD = null, NumVarStatMod givenWindup = null, NumVarStatMod givenExit = null, bool givenStatus = true)
	{
		if (givenCD != null)
		{
			CooldownMultiStat.Modify(givenCD, givenStatus);
		}
		if (givenWindup != null)
		{
			WindupMultiStat.Modify(givenWindup, givenStatus);
		}
		if (ExitMultiStat != null)
		{
			ExitMultiStat.Modify(givenExit, givenStatus);
		}
	}

	public void RegisterSkill(bool makeAvailableToAI = true, bool addToCooldowns = true)
	{
		if (makeAvailableToAI)
		{
			parent.availableEnemySkillsDict[skillID] = this;
		}
		else
		{
			parent.availableEnemySkillsDict.Remove(skillID);
		}
		if (addToCooldowns)
		{
			parent.cooldownManager.Add(skillID, cooldownTime);
			cooldownRef = parent.cooldownManager.cooldowns[skillID];
		}
		registered = true;
	}

	public void InitChargeSkillSettings(int maxCharges, float cooldownTime)
	{
		isChargeSkill = true;
		cooldownRef.isChargeSkill = true;
		cooldownRef.chargeCount = maxCharges;
		cooldownRef.MaxChargeCount = maxCharges;
		cooldownRef.remainingTimeStopwatchID = -1;
		cooldownRef.MaxTime = cooldownTime;
	}

	public bool BaseSkillIsReady()
	{
		if (parent.CurrentDifficulty < requiredDifficultyLevel)
		{
			return false;
		}
		if (isChargeSkill)
		{
			return parent.cooldownManager.cooldowns[skillID].chargeCount > 0;
		}
		return parent.cooldownManager.CheckCooldown(skillID);
	}

	public virtual bool IsReady()
	{
		return BaseSkillIsReady();
	}

	public bool Transition(bool checkIsReady = true)
	{
		if (fsm.currentStateName.Contains(skillID) || (checkIsReady && !IsReady()))
		{
			return false;
		}
		fsm.ChangeState(skillID, allowSelfTransition: true);
		return true;
	}

	public virtual void ExitTransition()
	{
		parent.HandleExitTransitions();
	}

	public void StartCooldown(float overrideValue = -1f)
	{
		if (!registered || (cooldownTime <= 0f && overrideValue <= 0f) || parent == null)
		{
			return;
		}
		if (isChargeSkill)
		{
			if (cooldownRef.chargeCount > 0)
			{
				cooldownRef.chargeCount--;
			}
			parent.StartCoroutine(parent.cooldownManager.StartChargeCounter(skillID));
		}
		else
		{
			parent.cooldownManager.StartCooldownTimer(skillID, overrideValue);
		}
	}

	public override void OnEnter()
	{
		parent.enemySkillUseInProgress = true;
		StartCooldown();
		currentDiffValue = parent.DifficultyValue;
		isLegendary = parent.IsLegendary;
		UpdateTargetVector();
		if (parent.closestTargetInfo != null)
		{
			parent.FaceTarget(parent.closestTargetInfo.position, parent.animFacingDirections);
		}
		if (usePowerUpEffect)
		{
			ActivatePowerUpEffect(spellCastColor);
		}
		windupComplete = false;
		exitQueued = false;
	}

	public override void Update()
	{
		if (!WindupCheck)
		{
			if (ChaosStopwatch.Check(windupStopwatchID))
			{
				ExecuteSkill();
			}
			else
			{
				WindupUpdate();
			}
		}
		else if (exitQueued && ChaosStopwatch.Check(exitStopwatchID))
		{
			ExitTransition();
		}
	}

	public override void OnExit()
	{
		parent.enemySkillUseInProgress = false;
		if (usePowerUpEffect)
		{
			DeactivatePowerUpEffect();
		}
	public bool multiAnimIdle;

	public bool resetAlert;

	private ChaosQuickStopwatch checkQSW;

	public IdleState(string newName, FSM newFSM, Enemy newEnt)
		: base(newName, newFSM, newEnt)
	{
		checkQSW = new ChaosQuickStopwatch(UnityEngine.Random.Range(0.5f, 0.75f));
	}

	public override void OnEnter()
	{
		parent.alerted = parent.spawnAlerted || (!resetAlert && parent.alerted);
		parent.RandomizeFacingDir();
		parent.anim.Play((!multiAnimIdle) ? "Idle" : "IdleDown");
	}

	public override void Update()
	{
		if (checkQSW.IsRunning)
		{
			return;
		}
		checkQSW.IsRunning = true;
		if (HandleTargetAcquisition())
		{
			if (!parent.alerted)
			{
				parent.RandomizeExtraSkillCDs();
			}
			parent.HandleExitTransitions(setAlert: true);
		}
	}

	public virtual bool HandleTargetAcquisition()
	{
		if (parent.UpdateTargetInfo() != null && (parent.alerted || Entity.HasLineOfSight(parent.transform.position, parent.closestTargetInfo.position, parent.CurrentAlertRadius, ChaosCollisions.layerAllWallAndObst)) && parent.CanApproachTarget(parent.transform.position, parent.closestTargetInfo.position, parent.CurrentAlertRadius, parent.lineOfSightLayerMask, parent.traversableNodeMap))
		{
			return true;
		}
		return false;
	}
}

public class IdleRoamState : IdleState
{
	public float roamDelay = 1f;

	public float randomRoamDelay = 1f;

	public int roamStopwatchID;

	public IdleRoamState(string newName, FSM newFSM, Enemy newEnt)
		: base(newName, newFSM, newEnt)
	{
		resetAlert = false;
	}

	public override void OnEnter()
	{
		base.OnEnter();
		roamStopwatchID = ChaosStopwatch.Begin(((!(randomRoamDelay > 0f)) ? 0f : UnityEngine.Random.Range(0f, randomRoamDelay)) + roamDelay);
	}

	public override void Update()
	{
		if (parent.alerted)
		{
			base.Update();
		}
		else if (ChaosStopwatch.Check(roamStopwatchID))
		{
			fsm.ChangeState("Roam");
		}
	}
}

public class GoBackState : State<Enemy>
{
	public bool forceGoBack;

	public GoBackState(string newName, FSM newFSM, Enemy newEnt)
		: base(newName, newFSM, newEnt)
	{
	}

	public override void OnEnter()
	{
		parent.alerted = false;
		parent.anim.PlayDirectional("Run" + ((parent.animFacingDirections != 2) ? parent.facingDirection.ToString() : "Right"));
		parent.requestPathStopwatchID = -1;
	}

	public override void Update()
	{
		if (forceGoBack || parent.UpdateTargetInfo(-1f, reqLOS: true) == null)
		{
			parent.MoveToTargetOrFollowPath(chasingTarget: false, parent.transform.position, parent.myOrigin, 999f, 0.5f);
		}
		else
		{
			parent.HandleExitTransitions();
		}
	}
}

public class ChaseState : State<Enemy>
{
	public float chaseRadius;

	public float goBackRadius;

	public ChaseState(string newName, FSM newFSM, Enemy newEnt)
		: base(newName, newFSM, newEnt)
	{
	}

	public override void OnEnter()
	{
		chaseRadius = ((!parent.surroundTarget) ? parent.attackRadius : parent.surroundRadius);
		goBackRadius = ((!parent.alerted) ? parent.escapeRadius : parent.maxAlertDistance);
		parent.anim.PlayDirectional("Run" + ((parent.animFacingDirections != 2) ? parent.facingDirection.ToString() : "Right"));
		parent.requestPathStopwatchID = -1;
		parent.alerted = true;
	}

	public override void Update()
	{
		parent.UpdateTargetInfo(goBackRadius);
		if (parent.closestTargetInfo == null)
		{
			fsm.ChangeState((!fsm.HasState("GoBack")) ? fsm.defaultStateName : "GoBack");
		}
		else if (!parent.MoveToTargetOrFollowPath(chasingTarget: true, parent.transform.position, parent.closestTargetInfo.position, goBackRadius, chaseRadius))
		{
		}
	}

	public bool IsAtTarget()
	{
		return parent.movement.MoveToTarget(parent.closestTargetInfo.position, chaseRadius) && parent.HasTargetInfoLOS();
	}
}

public class RoamState : State<Enemy>
{
	public int maxRetries = 3;

	public float roamDistance = 6f;

	public int losLayerMask;

	public string animName = "Run";

	public bool updateFacingDirection = true;

	public Vector2 newPosition;

	public bool isRoaming;

public class AttackState(string newName, FSM newFSM, Enemy newEnt) : State<Enemy>(newName, newFSM, newEnt)
{
	public bool soundPlayed;

	public bool multiAnimAttack = true;

	public float atkAnimStartTime;

	public bool ignoreEndMovement;

	public override void OnEnter()
	{
		parent.FaceTarget(parent.closestTargetInfo.position);
		parent.anim.PlayDirectional("Attack" + ((!multiAnimAttack) ? string.Empty : parent.facingDirection.ToString()), -1, atkAnimStartTime);
		if (parent.movement != null && !ignoreEndMovement)
		{
			parent.movement.EndMovement();
		}
		if (parent.attack != null && parent.attackSkillID != string.Empty)
		{
			parent.attack.SetAttackInfo(parent.skillCategory, parent.attackSkillID);
		}
		soundPlayed = false;
	}

	public override void Update()
	{
		PlayAttackAudio();
		if (parent.anim.AnimPlayed())
		{
			ExitTransition();
		}
	}

	public override void OnExit()
	{
		if (parent.movement != null && !ignoreEndMovement)
		{
			parent.movement.EndMovement();
		}
		if (parent.surroundTarget)
		{
			parent.ReleaseSurroundPoint();
		}
	}

	public void PlayAttackAudio()
	{
		if (!soundPlayed && parent.attackAudioID != string.Empty && parent.anim.AnimPlayed(parent.attackAnimAudioPlayTime))
		{
			soundPlayed = true;
			string attackAudioID = parent.attackAudioID;
			Vector2? soundOrigin = parent.transform.position;
	private int hurtAudioCount = -1;

	public new Enemy parent;

	public EnemyHurtState(string newName, FSM newFSM, Enemy newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
		if (parent.hurtAudioIDs != null)
		{
			hurtAudioCount = parent.hurtAudioIDs.Length;
		}
	}

	public override void OnEnter()
	{
		base.OnEnter();
		if (!parent.alerted)
		{
			parent.alerted = true;
			if (parent.canAlertOthers)
			{
				parent.AlertNearbyEnemies();
			}
		}
		PlayHurtAudio();
	}

	public override void ExitTransition()
	{
		if (fsm.nextStateName != name)
	public EnemyDeadState(string newName, FSM newFSM, Enemy newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
		isDead = false;
		lootSpawnLocation = Vector3.zero;
		if (parent.deadAudioIDs != null)
		{
			deadAudioCount = parent.deadAudioIDs.Length;
		}
	}

	public override void OnEnter()
	{
		if (isDead)
		{
			return;
		}
		base.OnEnter();
		if (parent.canAlertOthers)
		{
			parent.AlertNearbyEnemies();
		}
		EnemyDropLoot();
		if (playDeadEffectAudio)
		{
			PlayDeadAudio();
		}
		parent.ReleaseSurroundPoint();
		parent.currentGroup.Remove(parent.gameObject);
		GameDataManager.gameData.gameStats.EnemyDefeated(parent.enemyTypeString);
		isDead = true;
		Level.enemiesDefeatedCount++;
		lastAtk = parent.health.lastAttack;
		if (lastAtk != null && lastAtk.entity is Player)
		{
			if (parent.countDeathInStats)
			{
				(lastAtk.entity as Player).OnEnemyKill(parent);
			}
			(lastAtk.entity as Player).OnEnemyKillAbs(parent, lastAtk);
		}
	}

	public override void Update()
	{
