			}
			else
			{
				parent.GetComponent<Enemy>().enabled = false;
			}
		}
	}

public override void Awake()
{
	skillCategory = globalEnemySkillCategory;
	base.Awake();
	multiAnimHurt = false;
	if (surroundPoints == null)
	{
		surroundPoints = new List<Vector2>();
		int num = 8;
		for (int i = 0; i < num; i++)
		{
			surroundPoints.Add(Globals.GetCirclePositionVector(num, i));
		}
	}
	availableEnemySkillsDict = new Dictionary<string, SkillState>();
	priorityEnemySkillsList = new List<SkillState>();
	enemySkillUseInProgress = false;
	cooldownManager = new CooldownManager();
	traversableNodeMap = Pathfinder.nodeMap;
	requestPathTime = UnityEngine.Random.Range(1.5f, 2f);
	enemyType = GetType();
	enemyTypeString = enemyType.Name;
	Transform transform = base.transform.Find("EnemySprite");
	if (transform != null)
	{
		spriteRenderer = transform.GetComponent<SpriteRenderer>();
	}
	leftHandTrans = base.transform.Find("EnemyLeftHand");
	rightHandTrans = base.transform.Find("EnemyRightHand");
	if (floorContact != null)
	{
		originalFloorContactLayermask = floorContact.layer;
	}
	InitAudio();
	InitFSM();
}

public virtual void InitFSM()
{
}
public bool CanApproachTarget(Vector3 startPos, Vector3 targetPos, float maxDist, LayerMask losLM, Dictionary<Vector2, Node> nodemap)
{
	return Entity.HasLineOfSight(startPos, targetPos, maxDist, losLM) || Pathfinder.GetPath(nodemap, targetPos, startPos, losLM) != null;
}

private void InitNearbyEnemyList()
{
	Vector2 a = transform.position;
	for (int num = GameController.enemies.Count - 1; num >= 0; num--)
	{
		GameObject gameObject = GameController.enemies[num];
		if (!(gameObject == null) && !(gameObject == base.gameObject) && Vector2.Distance(a, gameObject.transform.position) < alertNearbyEnemiesRadius)
		{
			Enemy component = gameObject.GetComponent<Enemy>();
			if (component != null)
			{
				if (!nearbyEnemyList.Contains(component))
				{
					nearbyEnemyList.Add(component);
				}
				if (!component.nearbyEnemyList.Contains(this))
				{
					component.nearbyEnemyList.Add(this);
				}
			}
		}
	}
}

public void AlertNearbyEnemies(bool setAlert = true, bool callExitTransitions = false)
{
	UpdateTargetInfo(maxAlertDistance);
	if (closestTargetInfo != null && closestTargetInfo.transform != null)
	{
		for (int num = nearbyEnemyList.Count - 1; num >= 0; num--)
		{
			Enemy enemy = nearbyEnemyList[num];
			if (!(enemy == null) && !enemy.alerted && enemy.canAlertOthers && (enemy.fsm.currentStateName.Contains("Idle") || enemy.fsm.currentStateName.Contains("GoBack")))
			{
				enemy.closestTargetInfo = closestTargetInfo;
				if (!enemy.alerted)
				{
					enemy.RandomizeExtraSkillCDs();
				}
				enemy.alerted = true;
			}
		}
	}
	if (setAlert)
	{
		if (!alerted)
		{
			RandomizeExtraSkillCDs();
		}
		alerted = true;
	}
	if (callExitTransitions && useExitTransitions && (fsm.currentStateName == "Idle" || fsm.currentStateName == "GoBack"))
	{
		HandleExitTransitions();
	}
}

public bool MoveToTargetOrFollowPath(bool chasingTarget, Vector3 startPos, Vector3 targetPos, float losRange, float moveToRadius = 0f, string moveAnimName = "Run", bool faceTarget = true)
{
	if (Entity.HasLineOfSight(startPos, targetPos, losRange, lineOfSightLayerMask))
	{
		ChaosStopwatch.Stop(requestPathStopwatchID);
		PlayAnimOnFaceDirChange(moveAnimName, targetPos, animFacingDirections, faceTarget);
		if (chasingTarget && HandleExtraSkills())
		{
			return true;
		}
		if (movement.MoveToTarget(targetPos, moveToRadius))
		{
			if (faceTarget)
			{
				FaceTarget(targetPos, animFacingDirections);
			}
			if (chasingTarget)
			{
				if (surroundTarget && fsm.HasState("Surround"))
				{
					fsm.ChangeState("Surround");
				}
				else if (fsm.HasState("Attack"))
				{
					fsm.ChangeState("Attack");
				}
				else
				{
					fsm.ChangeState(fsm.defaultStateName);
				}
			}
			else
			{
				fsm.ChangeState(fsm.defaultStateName);
			}
			return true;
		}
		return false;
	}
	if (chasingTarget && HandleExtraSkills(hasLOS: false))
	{
		return true;
	}
	if (ChaosStopwatch.Check(requestPathStopwatchID))
	{
		requestPathStopwatchID = ChaosStopwatch.Begin(requestPathTime);
		followingPath = false;
		if (FindAndTraversePath(traversableNodeMap, startPos, targetPos, minNodeDist, moveAnimName, faceTarget, animFacingDirections, startNew: true) == -1)
		{
			fsm.ChangeState((!chasingTarget || !fsm.HasState("GoBack")) ? fsm.defaultStateName : "GoBack");
			return true;
		}
		followingPath = true;
		return false;
	}
	if (followingPath && FindAndTraversePath(traversableNodeMap, startPos, targetPos, minNodeDist, moveAnimName, faceTarget, animFacingDirections) != 0)
	{
		followingPath = false;
		if (chasingTarget)
		{
			HandleExitTransitions(setAlert: true);
		}
		else
		{
			fsm.ChangeState(fsm.defaultStateName);
		}
		return true;
	}
	return false;
}

public virtual TargetInfo UpdateTargetInfo(float rangeOverride = -1f, bool reqLOS = false)
{
	closestTargetInfo = Entity.GetClosestTarget(targetGroup, transform.position, (!(rangeOverride > 0f)) ? CurrentAlertRadius : rangeOverride, onlyTargetPlayers, null, gameObject, reqLOS, reqLOS ? lineOfSightLayerMask : 0);
	return closestTargetInfo;
}

public virtual bool HasTargetInfoLOS()
{
	return closestTargetInfo != null && Entity.HasLineOfSight(transform.position, closestTargetInfo.position, CurrentAlertRadius, lineOfSightLayerMask);
}

public virtual void HandleExitTransitions(bool setAlert = false)
{
	if (!useExitTransitions)
	{
		return;
	}
	if (!alerted && canAlertOthers)
	{
		AlertNearbyEnemies(setAlert: false);
	}
	alerted = setAlert || alerted;
	UpdateTargetInfo();
	if (closestTargetInfo != null)
	{
		if (CanMove && fsm.HasState("Chase") && fsm.GetState("Chase") is ChaseState && !((ChaseState)fsm.GetState("Chase")).IsAtTarget())
		{
			fsm.ChangeState("Chase");
			return;
		}
		hasLOS = HasTargetInfoLOS();
		if (!HandleExtraSkills(hasLOS))
		{
			if (surroundTarget && fsm.HasState("Surround") && !fsm.currentStateName.Contains("Surround") && closestTargetInfo.distance <= surroundRadius)
			{
				fsm.ChangeState("Surround");
			}
			else if (hasLOS && closestTargetInfo.distance <= attackRadius && fsm.HasState("Attack"))
			{
				fsm.ChangeState("Attack", allowSelfTransition: true);
			}
			else
			{
				fsm.ChangeState(fsm.defaultStateName);
			}
		}
	}
	else if (CanMove && fsm.HasState("GoBack"))
	{
		fsm.ChangeState("GoBack");
	}
	else
	{
		fsm.ChangeState(fsm.defaultStateName);
	}
}

public bool HandleExtraSkills(bool hasLOS = true, bool updateTarget = false, bool updateLOS = false)
{
	if (enemySkillUseInProgress || !CanUseSkills)
	{
		return false;
	}
	if (updateTarget)
	{
		UpdateTargetInfo();
	}
	if (updateLOS)
	{
