using System;
using System.Collections.Generic;
using UnityEngine;

public class FSM : IFSM
{
	public IState currentState;

	public IState previousState;

	public IState nextState;

	private Dictionary<string, IState> states;

	public string queuedState;

	public bool queuedAllowSelfTransition;

	public string currentStateName => (currentState != null) ? currentState.name : string.Empty;

	public string previousStateName => (previousState != null) ? previousState.name : string.Empty;

	public string nextStateName => (nextState != null) ? nextState.name : string.Empty;

	public string defaultStateName { get; set; }

	public FSM()
	{
		states = new Dictionary<string, IState>();
		queuedState = string.Empty;
		queuedAllowSelfTransition = false;
	}

	public bool AnyStateUpdate()
	{
		if (queuedState != string.Empty)
		{
			ChangeState(queuedState, queuedAllowSelfTransition);
			queuedState = string.Empty;
			queuedAllowSelfTransition = false;
			return true;
		}
		return false;
	}

	public bool HasState(string stateName)
	{
		return states.ContainsKey(stateName);
	}

	public IState GetState(string stateName)
	{
		return (!HasState(stateName)) ? null : states[stateName];
	}

	public void QueueChangeState(string targetStateName, bool allowSelfTransition = false)
	{
		queuedState = targetStateName;
		queuedAllowSelfTransition = allowSelfTransition;
	}

	public void ChangeState(string targetStateName, bool allowSelfTransition = false)
	{
		if (currentState == null || !(currentState.name == targetStateName) || allowSelfTransition || targetStateName.Contains("Hurt") || targetStateName.Contains("Frozen"))
		{
			if (!states.ContainsKey(targetStateName))
			{
				Debug.Log(targetStateName + " not found!");
			}
			nextState = states[targetStateName];
			if (currentState != null)
			{
				currentState.OnExit();
			}
			previousState = currentState;
			currentState = nextState;
			nextState = null;
			currentState.OnEnter();
		}
	}

	public void ReplaceState(IState newState)
	{
		if (!states.ContainsKey(newState.name))
		{
			throw new Exception("Attempt to replace state that is not alreadypresent in the FSM: " + newState.name);
		}
		states[newState.name] = newState;
	}

	public void AddState(IState newState)
	{
		states.Add(newState.name, newState);
	}

	public void PrintAllStates()
	{
		foreach (KeyValuePair<string, IState> state in states)
		{
			Debug.Log(string.Concat("** FSM.STATE: [", state.Key, "] ** STATE.TYPE: [", state.Value.GetType(), "] **"));
		}
	}
}

