		parent.AllowHurtState(status: false);
		if (stunEffect != null)
		{
			stunEffect.Stop(!fsm.nextStateName.Contains("Dead") && fsm.nextStateName.Contains("Fall"));
			stunEffect = null;
		}
	}

	public virtual void HandleDurationIncrease(bool first = false)
	{
		if (first)
		{
			hitCounter = 1;
			hurtStopwatchID = ChaosStopwatch.Begin(baseHurtDuration);
			return;
		}
		if (lastAttackInfo != null && !lastAttackInfo.isStatusEffect)
		{
			hitCounter++;
		}
		hurtStopwatchID = ChaosStopwatch.Begin(Mathf.Min(maxHurtDuration, durationIncreaseMultiplier * baseHurtDuration / (float)hitCounter + ChaosStopwatch.GetRemainingTime(hurtStopwatchID)));
	}

	public virtual void HandleStunEffect()
	{
		if (base.stunEffect == null)
		{
			base.stunEffect = PoolManager.GetPoolItem<StunEffect>();
			base.stunEffect.fullStunOverride = stunOverrideValue;
			base.stunEffect.Play(hurtStopwatchID, parent.transform, Vector3.up * 3.25f);
		}
		else
		{
			StunEffect stunEffect = base.stunEffect;
			int givenStopwatchID = hurtStopwatchID;
			stunEffect.Readjust(-1f, givenStopwatchID);
		}
	}
}
