public override TargetInfo UpdateTargetInfo(float rangeOverride = -1f, bool reqLOS = false)
{
	bossTargetList = Entity.GetAllTargetsInRange(targetGroup, transform.position, (!(rangeOverride > 0f)) ? CurrentAlertRadius : rangeOverride, onlyTargetPlayers, null, gameObject, reqLOS, reqLOS ? lineOfSightLayerMask : 0);
	if (bossTargetList.Count > 0)
	{
		int index = UnityEngine.Random.Range(0, bossTargetList.Count);
		return closestTargetInfo = Entity.GetTargetInfoFromObject(bossTargetList[index], Vector2.Distance(transform.position, bossTargetList[index].transform.position));
	}
	return null;
}

public virtual void TransitionToNextState()
{
	attackIndex++;
	if (attackIndex < 0 || attackIndex >= attackIndexCurrentMax || UpdateTargetInfo() == null)
	{
		fsm.ChangeState(fsm.defaultStateName, allowSelfTransition: true);
	}
	else if (attackPatternIndex == 0 && attackIndex == attackIndexCurrentMax - 1 && bossUltimateState.UltIsReady)
	{
		bossUltimateState.queueUltimate = true;
		fsm.ChangeState(bossUltimateState.name, allowSelfTransition: true);
	}
	else
	{
		fsm.ChangeState(attackPatternList[attackPatternIndex][attackIndex].name, allowSelfTransition: true);
	}
}

public virtual void AllowHurtState(bool status)
{
	if (!(health == null))
	{
		health.ignoreHurtVarStat.Modify(bossIgnoreMod, !status);
		health.ignoreKnockbackVarStat.Modify(bossIgnoreMod, !status);
		health.flashRedOnHit = status;
		health.faceHurtDirection = status;
	}
}

