	private void PlayAnimation()
	{
		animIndex = (animIndex + UnityEngine.Random.Range(1, animCount)) % animCount;
		currentAnimName = animNames[animIndex];
		if (currentAnimName.Contains("Left"))
		{
			parent.isFacingRight = false;
			parent.facingDirection = FacingDirection.Left;
		}
		else if (currentAnimName.Contains("Right"))
		{
			parent.isFacingRight = true;
			parent.facingDirection = FacingDirection.Right;
		}
		parent.anim.PlayDirectional(currentAnimName);
		flexAudio = SoundManager.PlayAudio("FireBossFlex" + UnityEngine.Random.Range(0, 2));
	}
